"""Expected violation sets under the linkage-semantics policy.

Policy recap:
  * GPL-3.0 infects across static edges only.
  * AGPL-3.0 infects across static AND dynamic edges.
  * build_only edges never propagate obligations.
  * BSL-1.1 anywhere in the runtime closure (static+dynamic) of a
    distributed artifact -> distribution_restricted.
"""

import json
import os
import subprocess
import sys

import pytest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from audit import find_violations, load_graph  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))


def edge_tuples(violation):
    return tuple((e["from"], e["to"], e["type"]) for e in violation["path"])


def violations_as_set(graph_path):
    return {
        (v["artifact"], v["source"], v["license"], v["kind"], edge_tuples(v))
        for v in find_violations(load_graph(graph_path))
    }


# --------------------------------------------------------------------------
# Fixture graph: app -static-> libcore -dynamic-> libnet (AGPL);
#                app -build_only-> buildtool (GPL);
#                app -dynamic-> libui (GPL);
#                app -static-> libdb (BSL-1.1)
#
# Reasoned expectation:
#   AGPL-3.0 via [static, dynamic]  -> VIOLATION (agpl crosses both)
#   BSL-1.1  via [static]           -> VIOLATION (runtime closure)
#   GPL-3.0  via [build_only]       -> ok (build_only never propagates)
#   GPL-3.0  via [dynamic]          -> ok (GPL crosses static only)
# --------------------------------------------------------------------------

EXPECTED_MAIN = frozenset({
    (
        "app", "libnet", "AGPL-3.0", "agpl_infection",
        (("app", "libcore", "static"), ("libcore", "libnet", "dynamic")),
    ),
    (
        "app", "libdb", "BSL-1.1", "distribution_restricted",
        (("app", "libdb", "static"),),
    ),
})


def test_main_fixture_expected_violations():
    assert violations_as_set(os.path.join(HERE, "graph.json")) == EXPECTED_MAIN


def test_build_only_gpl_does_not_propagate():
    got = violations_as_set(os.path.join(HERE, "graph.json"))
    assert not any(source == "buildtool" for _, source, _, _, _ in got)


def test_dynamic_gpl_does_not_propagate():
    got = violations_as_set(os.path.join(HERE, "graph.json"))
    assert not any(source == "libui" for _, source, _, _, _ in got)


def test_each_reported_violation_carries_edge_types():
    for v in find_violations(load_graph(os.path.join(HERE, "graph.json"))):
        assert v["path"], "violation must include a propagation path"
        for edge in v["path"]:
            assert set(edge) == {"from", "to", "type"}


# --------------------------------------------------------------------------
# No-violation graph: MIT static dep, GPL behind build_only and behind a
# bare dynamic edge — none of those propagate obligations.
# --------------------------------------------------------------------------

def test_no_violation_graph(tmp_path):
    graph = {
        "artifacts": {
            "app": "Apache-2.0",
            "util": "MIT",
            "generator": "GPL-3.0",
            "client": "GPL-3.0",
            "agpldep": "AGPL-3.0",
        },
        "edges": [
            {"from": "app", "to": "util", "type": "static"},
            {"from": "app", "to": "generator", "type": "build_only"},
            {"from": "app", "to": "client", "type": "dynamic"},
            {"from": "app", "to": "agpldep", "type": "build_only"},
        ],
    }
    path = tmp_path / "clean.json"
    path.write_text(json.dumps(graph))
    assert violations_as_set(str(path)) == frozenset()


# --------------------------------------------------------------------------
# Diamond graph: common (GPL-3.0) reached from app by a pure-static path
# and by a build_only-rooted path. The static path governs: exactly one
# violation, reported along the static/static route only.
# --------------------------------------------------------------------------

EXPECTED_DIAMOND = frozenset({
    (
        "app", "common", "GPL-3.0", "gpl_infection",
        (("app", "liba", "static"), ("liba", "common", "static")),
    ),
})


def test_diamond_static_path_governs():
    got = violations_as_set(os.path.join(HERE, "graph_diamond.json"))
    assert got == EXPECTED_DIAMOND


# --------------------------------------------------------------------------
# CLI behaviour: JSON on stdout, exit 1 with violations, exit 0 when clean.
# --------------------------------------------------------------------------

@pytest.mark.parametrize("fixture,expected_code", [
    ("graph.json", 1),
    ("graph_diamond.json", 1),
])
def test_cli_exit_codes_and_json(fixture, expected_code):
    proc = subprocess.run(
        [sys.executable, os.path.join(HERE, "audit.py"),
         os.path.join(HERE, fixture)],
        capture_output=True, text=True,
    )
    assert proc.returncode == expected_code
    parsed = json.loads(proc.stdout)
    assert isinstance(parsed, list) and parsed


def test_cli_clean_graph_exits_zero(tmp_path):
    graph = {"artifacts": {"solo": "Apache-2.0"}, "edges": []}
    path = tmp_path / "solo.json"
    path.write_text(json.dumps(graph))
    proc = subprocess.run(
        [sys.executable, os.path.join(HERE, "audit.py"), str(path)],
        capture_output=True, text=True,
    )
    assert proc.returncode == 0
    assert json.loads(proc.stdout) == []

