def distributed_roots(graph):
    """Artifacts whose runtime closure is audited.

    Uses the explicit ``distributed`` list when present, otherwise falls
    back to all artifacts with no incoming edges (top-level artifacts).
    """
    if "distributed" in graph:
        roots = graph["distributed"]
        unknown = [r for r in roots if r not in graph["artifacts"]]
        if unknown:
            raise ValueError(f"unknown distributed artifacts: {unknown}")
        return sorted(roots)
    targets = {edge["to"] for edge in graph.get("edges", [])}
    return sorted(a for a in graph["artifacts"] if a not in targets)

